"""Curated art-direction vocabulary used by the studio and image prompt builder."""

from __future__ import annotations

from typing import Any, Dict, Iterable


def _style(name: str, category: str, description: str, direction: str, palette: list[str], keywords: Iterable[str]) -> Dict[str, Any]:
    return {"name": name, "category": category, "description": description, "direction": direction, "palette": palette, "keywords": list(keywords)}


