DEFAULT_STYLE_KEY = "painterly-realism"


def detect_style_key(prompt: str) -> str:
    normalized = " ".join(prompt.lower().replace("-", " ").split())
    best_key, best_score = DEFAULT_STYLE_KEY, 0
    for key, style in ART_STYLES.items():
        candidates = [key.replace("-", " "), style["name"].lower(), *style["keywords"]]
        score = sum(max(1, len(candidate.split())) for candidate in candidates if candidate in normalized)
        if score > best_score:
            best_key, best_score = key, score
    return best_key


def public_style_catalog() -> list[dict[str, Any]]:
    return [{"id": key, "name": value["name"], "category": value["category"], "description": value["description"], "palette": value["palette"]} for key, value in ART_STYLES.items()]
